function tripDetail(id){let tr=(state.data.trips||[]).find(x=>x.id===id);if(!tr)return `<div class="empty-state">${t('unknown')}</div>`;let inv=tr.inventory||[];let route=tr.current_route||tr.route;return `<section class="page-head"><div><button class="back" data-action="back">← ${t('back')}</button><h1>${t('journeyDetail')}</h1></div><span class="status-tag">${statusName(tr.status)}</span></section><section class="panel"><div class="route-labels"><b>${esc(labelOf(tr.origin))}</b><span>${t('toWord')}</span><b>${esc(labelOf(tr.destination))}</b></div><p>${fmtTime(tr.departure)}</p>${routeSvg(route)}<div class="stats-strip"><span><b>${route?.distance_m?`${new Intl.NumberFormat(locale(),{maximumFractionDigits:1}).format(route.distance_m/1000)} ${t('km')}`:t('unknown')}</b><small>${t('distance')}</small></span><span><b>${dur(route?.duration_s)}</b><small>${t('duration')}</small></span><span><b>${esc(route?.provider||'')}</b><small>${t('routeSource')}</small></span></div>${routeAttribution()}<div class="inventory"><h2>${t('segmentInventory')}</h2><p class="muted">${t('inventoryPosition')}</p>${inv.length?inv.map((s,i)=>`<div class="inventory-row"><span>${new Intl.NumberFormat(locale(),{maximumFractionDigits:1}).format((Number(s.from_m)/1000))}–${new Intl.NumberFormat(locale(),{maximumFractionDigits:1}).format((Number(s.to_m)/1000))} ${t('km')}</span><div class="seatbar" aria-label="${s.occupied} ${t('occupied')}, ${s.available} ${t('free')}"><i style="width:${Math.min(100,100*s.occupied/Math.max(1,s.occupied+s.available))}%"></i></div><b>${new Intl.NumberFormat(locale()).format(Number(s.occupied))} ${t('occupied')} / ${new Intl.NumberFormat(locale()).format(Number(s.available))} ${t('free')}</b></div>`).join(''):`<p>${t('noData')}</p>`}</div><div class="action-row">${tr.status==='published'?`<button class="primary" data-action="start-trip" data-id="${escAttr(tr.id)}" ${state.busy?'disabled':''}>${state.busy?t('pending'):t('startTrip')}</button><button class="secondary" data-action="cancel-trip" data-id="${escAttr(tr.id)}" ${state.busy?'disabled':''}>${state.busy?t('pending'):t('cancelTrip')}</button>`:''}${tr.status==='started'?`<button class="primary" data-action="complete-trip" data-id="${escAttr(tr.id)}" ${state.busy?'disabled':''}>${state.busy?t('pending'):t('completeTrip')}</button>`:''}</div></section>`}
function livePage(id){return makeTripViews({state,t,icon,esc,escAttr,fmtTime,labelOf,bookingRouteMap}).livePage(id)}
function mountLivePage(){const element=app.querySelector('[data-live-booking]');if(!element)return;const id=element.dataset.liveBooking;if(state.liveCleanup&&state.liveBookingId===id&&state.liveElement===element)return;if(state.liveCleanup){state.liveCleanup();state.liveCleanup=null}const booking=(state.data.bookings||[]).find(x=>x.id===id);if(!booking)return;const trip=(state.data.trips||[]).find(x=>x.id===booking.trip_id);const liveBooking={...booking,route:booking.route||booking.trip_route||trip?.current_route||trip?.route};state.liveBookingId=id;state.liveElement=element;state.liveCleanup=mountLiveLocation({element,booking:liveBooking,viewerId:state.user?.id,lang:state.lang,t,api,labelPoint:labelOf,getCsrf:()=>state.csrf,onExpired:async()=>{await expireSession();render()}})}
function reportStatusName(v){return ({open:t('reportOpen'),resolved:t('reportResolved')})[v]||t('unknown')}
function safetyPage(id){return makeTripViews({state,t,icon,esc,escAttr,fmtTime,labelOf,bookingRouteMap}).safetyPage(id)}
function adminReports(rows=[]){const mayResolve=canResolveSafety();return `<section class="panel"><h2>${t('safetyReports')}</h2>${rows.length?rows.map(r=>`<article class="report-row"><div class="section-row"><b>${t(`category_${r.category}`)} · ${reportStatusName(r.status)}</b><small>${fmtTime(r.created_at)}</small></div><p>${esc(r.details)}</p>${r.resolution?`<p>${t('resolution')}: ${esc(r.resolution)}</p>`:mayResolve?`<form class="resolve-form" data-report-id="${escAttr(r.id)}"><label class="field">${t('resolution')}<textarea name="resolution" minlength="10" maxlength="1000" required rows="3">${esc(state.adminResolutionDrafts[r.id]||'')}</textarea></label><button type="button" class="secondary" data-action="resolve-report" data-id="${escAttr(r.id)}" ${state.busy?'disabled':''}>${state.busy?t('pending'):t('resolveReport')}</button></form>`:''}</article>`).join(''):`<p>${t('noData')}</p>`}</section>`}
function bookingRouteMap(id){
  const booking=(state.data.bookings||[]).find(x=>x.id===id);if(!booking)return '';
  const trip=(state.data.trips||[]).find(x=>x.id===booking.trip_id);
  const route=booking.route||booking.trip_route||booking.match?.route||trip?.current_route||trip?.route;
  const points=[booking.match?.routed_pickup||booking.pickup,booking.match?.routed_dropoff||booking.dropoff].filter(Boolean);
  return `<div class="rating-route-map journey-map-shell"><div class="journey-map" data-journey-route-map data-route-coordinates="${escAttr(JSON.stringify(route?.coordinates||[]))}" data-route-points="${escAttr(JSON.stringify(points))}" aria-label="${t('routeAria')}"></div></div>`;
}
function ratePage(id){return makeTripViews({state,t,icon,esc,escAttr,fmtTime,labelOf,bookingRouteMap}).ratePage(id)}
function pct(v){return v==null?'—':`${Number(v).toFixed(1)}%`}
function operationsPage(){if(!canReadOps())return `<section class="panel"><h1>${t('operations')}</h1><p>${t('operationsUnavailable')}</p></section>`;let d=state.ops;if(!d)return `<div class="empty-state"><p>${t('loading')}</p></div>`;let m=d.metrics||{};let stats=[['users',d.users?.length],['trips',d.trips?.length],['requests',d.requests?.length],['matches',d.matches?.length],['ratings',d.ratings?.length],['events',d.events?.length],['safetyReports',(d.safety_reports||d.reports)?.length],['routes',d.route_calculations?.length]];let ms=[['metricsTraditional',m.traditional_match_count],['metricsAware',m.route_aware_match_count],['metricsIncremental',m.incremental_matches],['metricsLift',pct(m.match_lift_percentage)],['completeSearches',m.complete_searches],['matchedSearches',m.matched_searches],['acceptedBookings',m.accepted_bookings],['completedSegments',m.completed_segments],['completedTrips',m.completed_trips],['acceptance',pct(m.driver_acceptance_rate)],['conversion',pct(m.booking_conversion)],['metricDetour',m.median_driver_detour_minutes==null?'—':`${m.median_driver_detour_minutes} min`],['driverCancels',m.driver_cancellations],['passengerCancels',m.passenger_cancellations],['repeatDrivers',m.repeat_drivers],['repeatPassengers',m.repeat_passengers]];return `<section class="page-head"><div><h1>${t('adminTitle')}</h1><p class="muted">${t('developmentRows')}</p></div><button class="secondary" data-action="refresh">${t('refresh')}</button></section><div class="metric-grid">${stats.map(([k,v])=>`<div><small>${t(k)}</small><b>${v??0}</b></div>`).join('')}</div><section class="panel"><h2>${t('metrics')}</h2><div class="ops-metrics">${ms.map(([k,v])=>`<div><span>${t(k)}</span><b>${v??'—'}</b></div>`).join('')}</div><p class="baseline">${esc(m.baseline_definition||'')}</p></section>${adminReports(d.safety_reports||d.reports||[])}${[['users',d.users],['trips',d.trips],['requests',d.requests],['matches',d.matches],['bookings',d.bookings],['ratings',d.ratings],['events',d.events],['route_calculations',d.route_calculations]].map(([key,rows])=>tableSection(key,rows)).join('')}`}
function tableSection(key,rows=[]){let cols=Array.from(new Set((rows||[]).flatMap(o=>Object.keys(o||{})))).slice(0,8);return `<details class="table-section"><summary>${t(key)} <b>${rows?.length||0}</b></summary>${rows?.length?`<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr>${cols.map(c=>`<td>${esc(typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<p>${t('noData')}</p>`}</details>`}
function setSharedRoutePoints(values){for(const name of ['origin','destination']){const lat=values?.[`${name}_lat`],lon=values?.[`${name}_lon`],label=values?.[`${name}_label`];state.routePoints[name]=label&&lat!==''&&lon!==''&&Number.isFinite(Number(lat))&&Number.isFinite(Number(lon))?{label,lat:Number(lat),lon:Number(lon)}:null}}
function sharedRouteValues(){const out={};for(const name of ['origin','destination']){const p=state.routePoints[name];if(p){out[`${name}_label`]=p.label;out[`${name}_lat`]=p.lat;out[`${name}_lon`]=p.lon}}return out}
function prepareComposerDraft(id){const base=state.formDrafts[id]||{id,values:{}};state.form={id,values:{...(base.values||{}),...sharedRouteValues()}}}
function openComposer(id){if(id==='drive-form'&&!canDrive()){captureDraft();state.menuOpen=false;nav('become-driver');return}captureDraft();const values={...(state.formDrafts[id]?.values||{}),...sharedRouteValues()};state.formDrafts[id]={id,values};state.form={id,values};state.menuOpen=false;nav(id)}
function captureDraft(){if(state.skipCaptureOnce){state.skipCaptureOnce=false;return}const form=app.querySelector('form#home-route-form,form#drive-form,form#search-form,form#rate-form,form#login-form,form#safety-form');if(!form)return;const out={id:form.id,values:{}};new FormData(form).forEach((v,k)=>out.values[k]=v);state.form=out;if(['home-route-form','drive-form','search-form'].includes(form.id)){state.formDrafts[form.id]=out;setSharedRoutePoints(out.values)}}
function restoreDraft(){const d=state.form;if(!d)return;const form=document.getElementById(d.id);if(!form)return;for(const [k,v] of Object.entries(d.values)){const el=form.elements[k];if(el)el.value=d.id==='search-form'&&k==='seats'?'1':v}for(const name of ['origin','destination']){const label=form.elements[`${name}_label`],lat=Number(form.elements[`${name}_lat`]?.value),lon=Number(form.elements[`${name}_lon`]?.value);const preset=(state.boot?.places||[]).find(p=>Number(p.lat)===lat&&Number(p.lon)===lon&&p.label===label?.value);if(preset&&placeNames[state.lang]?.[preset.label])label.value=placeNames[state.lang][preset.label]}}
function mountJourneyMapForView(){
  const cleanups=[];
  const element=app.querySelector('#journey-map');
  if(element){
    const form=app.querySelector('#home-route-form,#drive-form,#search-form');
    const points=form?['origin','destination'].map(name=>getPoint(new FormData(form),name)).filter(Boolean):[];
    cleanups.push(mountJourneyMap(element,{points,route:currentRoute()==='drive-form'?state.preview?.route:undefined,lang:state.lang,t}));
  }
  for(const mapElement of app.querySelectorAll('[data-journey-route-map]')){
    let coordinates=[],points=[];
    try{coordinates=JSON.parse(mapElement.dataset.routeCoordinates||'[]');points=JSON.parse(mapElement.dataset.routePoints||'[]')}catch{}
    if(!Array.isArray(coordinates))coordinates=[];if(!Array.isArray(points))points=[];
    cleanups.push(mountJourneyMap(mapElement,{points,route:{coordinates},lang:state.lang,t}));
  }
  state.journeyMapCleanup=()=>cleanups.forEach(dispose=>dispose());
}
function render(){
  community.unmount?.();
  (state.tripSharingCleanups || []).forEach((cleanup) => cleanup());
  state.tripSharingCleanups = [];
  captureDraft();
  if(state.journeyMapCleanup){state.journeyMapCleanup();state.journeyMapCleanup=null}
  document.documentElement.lang=state.lang;
  document.title=t('documentTitle');
  const r=currentRoute();
  if(state.user){
    const requested=location.hash.replace(/^#\/?/,'');
    if(requested!==r)history.replaceState(history.state,'',`${location.pathname}${location.search}#/${r}`);
    if(r==='home')prepareComposerDraft('home-route-form');
    else if(r==='drive-form')prepareComposerDraft('drive-form');
    else if(r==='search-form')prepareComposerDraft('search-form');
  }
  state.renderedRoute=r;
  if(!state.boot){
    app.innerHTML=header()+`<main class="main logged-out">${state.error?`<div class="alert error" role="alert">${esc(errorMessage(state.error))} <button class="text-button" data-action="retry-bootstrap">${t('retry')}</button></div>`:`<div class="loading">${t('loading')}</div>`}</main>`;
    wire();return;
  }
  if(!state.user){
    app.innerHTML=header()+`<main class="main logged-out">${state.error?`<div class="alert error" role="alert">${esc(errorMessage(state.error))}</div>`:''}${loginPage()}</main><footer class="safety">${t('safety')}</footer>`;
    restoreDraft();wire();return;
  }
  let content='';
  if(r==='home')content=homePage();
  else if(r==='drive-form')content=driveForm();
  else if(r==='become-driver')content=renderBecomeDriver({state,t,icon});
  else if(r==='search-form')content=searchForm();
  else if(r==='results')content=resultsPage();
  else if(r==='journeys')content=journeyPage();
  else if(r==='bookings')content=bookingPage();
  else if(r==='inbox')content=inboxPage();
  else if(r==='profile')content=community.profilePage();
  else if(r==='chats')content=community.chatsPage();
  else if(r==='notifications')content=community.notificationsPage();
  else if(r.startsWith('chat/'))content=community.chatPage(decodeURIComponent(r.slice(5)));
  else if(r.startsWith('complete/'))content=makeTripViews({state,t,icon,esc,escAttr,fmtTime,labelOf,bookingRouteMap}).completedTripPage(decodeURIComponent(r.slice(9)))||bookingPage();
  else if(r.startsWith('trip/'))content=tripDetail(decodeURIComponent(r.slice(5)));
  else if(r.startsWith('rate/'))content=ratePage(decodeURIComponent(r.slice(5)));
  else if(r.startsWith('live/'))content=livePage(decodeURIComponent(r.slice(5)));
  else if(r.startsWith('safety/'))content=safetyPage(decodeURIComponent(r.slice(7)));
  else if(r==='operations'&&isStaff())content=operationsPage();
  else content=homePage();
  app.innerHTML=shell(content);
  restoreDraft();wire();initJourneyTimeInputs();mountJourneyMapForView();
  const isLive=currentRoute().startsWith('live/');
  if(state.liveCleanup&&(!isLive||state.liveElement?.isConnected===false)){state.liveCleanup();state.liveCleanup=null;state.liveBookingId=null;state.liveElement=null}
  if(isLive)mountLivePage();
  for (const element of app.querySelectorAll('[data-trip-sharing]')) {
    state.tripSharingCleanups.push(mountTripSharing({element,bookingId:element.dataset.bookingId,api,lang:state.lang,t,viewerId:state.user?.id||''}));
  }
  community.mount?.({root:app,view:r.startsWith('chat/')?'chat':r,bookingId:r.startsWith('chat/')?decodeURIComponent(r.slice(5)):''});
}
function wire(){document.querySelectorAll('form [required]').forEach(el=>{el.addEventListener('invalid',ev=>{const v=ev.target.validity;if(v.customError)return;ev.target.setCustomValidity(v.valueMissing?t('required'):v.badInput?t('invalidNumber'):v.rangeOverflow||v.rangeUnderflow?t('rangeInvalid'):v.tooShort||v.tooLong?(ev.target.form?.classList.contains('resolve-form')?t('invalidResolution'):ev.target.form?.id==='safety-form'?t('invalidReportDetails'):t('required')):ev.target.type==='datetime-local'?t('invalidDate'):t('required'))});['input','change'].forEach(type=>el.addEventListener(type,()=>el.setCustomValidity('')))});document.querySelector('#language')?.addEventListener('change',e=>{captureDraft();changeLanguage(e.target.value);render()});document.querySelector('#login-form')?.addEventListener('submit',login);document.querySelector('#drive-form')?.addEventListener('submit',preview);document.querySelector('#search-form')?.addEventListener('submit',search);document.querySelector('#rate-form')?.addEventListener('submit',rate);document.querySelector('#safety-form')?.addEventListener('submit',submitSafety);document.querySelectorAll('[data-location]').forEach(b=>b.addEventListener('click',()=>chooseLocation(b.closest('form'),b.dataset.location)));document.querySelectorAll('[data-account-choice]').forEach(b=>b.addEventListener('click',()=>{const select=document.querySelector('#account-choice');if(!select)return;select.value=b.dataset.accountChoice;document.querySelectorAll('[data-account-choice]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))})}));document.querySelectorAll('[data-seat-step]').forEach(b=>b.addEventListener('click',()=>{const input=b.closest('.stepper-control')?.querySelector(`input[name="${CSS.escape(b.dataset.seatField)}"]`);if(!input)return;const min=Number(input.min||1),max=Number(input.max||6),value=Math.max(min,Math.min(max,Number(input.value||min)+Number(b.dataset.seatStep)));input.value=String(value);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}))}));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action,b.dataset.id)));}
function markPending(form,label){const b=form?.querySelector('button[type=submit],button:not([type])');if(b){b.disabled=true;b.dataset.before=b.textContent;b.textContent=label}}
function clearPending(){document.querySelectorAll('button[data-before]').forEach(b=>{b.disabled=false;b.textContent=b.dataset.before;delete b.dataset.before})}
async function login(e){e.preventDefault();if(state.busy)return;let f=new FormData(e.target);state.busy=true;markPending(e.target,t('pending'));try{let out=await api('/api/login','POST',{account:f.get('account'),password:f.get('password')});state.user=out.user;state.form=null;state.formDrafts={};state.routePoints={origin:null,destination:null};state.passwordVisible=false;state.skipCaptureOnce=true;await refreshState();state.notice='';state.noticeKey=null;state.error='';const landing=landingRoute();if(landing==='operations'&&canReadOps())await loadOps();nav(landing)}catch(err){if(err.status===401&&err.path!=='/api/login')await expireSession();else setError(err)}finally{state.busy=false;clearPending();render()}}
function initJourneyTimeInputs(){
  const form=document.querySelector('#search-form,#drive-form'); if(!form)return;
  const start=form.elements.window_start,end=form.elements.window_end,departure=form.elements.departure;
  seedBlankJourneyTimes({start,end,departure});
  if(start&&end)form.journeyTimes=bindPickupWindow(start,end,{t});
  else if(departure){
    const refresh=()=>{const bounds=seedJourneyTimes();departure.min=bounds.min;departure.max=bounds.max;const result=validateJourneyTime(departure.value);departure.setCustomValidity(result.valid?'':t(result.errorKey));return result};
    for(const event of ['focus','input','change'])departure.addEventListener(event,refresh);
    form.journeyTimes={validate:refresh};refresh();
  }
  for(const input of [start,end,departure].filter(Boolean)){
    const note=document.createElement('small');note.className='field-error';note.setAttribute('aria-live','polite');note.id=`${input.name}-error`;input.setAttribute('aria-describedby',note.id);input.closest('label').append(note);
    input.addEventListener('input',()=>{note.textContent='';input.removeAttribute('aria-invalid')});
  }
}
function validateJourneyTimeForm(form){
  const result=form.journeyTimes?.validate();
  const valid=form.reportValidity();
  for(const input of form.querySelectorAll('input[type="datetime-local"]')){
    const note=form.querySelector(`#${input.name}-error`);if(note)note.textContent=input.validationMessage;
    input.setAttribute('aria-invalid',String(!input.validity.valid));
  }
  return result?.valid!==false&&valid;
}
function localIso(v){if(!v)throw new Error('Enter a date and time.');return `${v}:00+05:30`}
async function preview(e){e.preventDefault();if(state.busy)return;if(!validateJourneyTimeForm(e.target))return;const f=new FormData(e.target);if(!getPoint(f,'origin')||!getPoint(f,'destination')){setError(t('chooseLocation'));e.target.querySelector('[data-location]')?.focus();render();return}state.busy=true;markPending(e.target,t('pending'));try{const out=await api('/api/preview','POST',{origin:getPoint(f,'origin'),destination:getPoint(f,'destination'),departure:localIso(f.get('departure')),seats:Number(f.get('seats')),max_detour_minutes:Number(f.get('max_detour_minutes'))});state.preview=out.preview;setNotice(t('previewSaved'))}catch(err){if(err.status===401)await expireSession();else setError(err)}finally{state.busy=false;clearPending();render()}}
async function search(e){e.preventDefault();if(state.busy)return;if(!validateJourneyTimeForm(e.target))return;const f=new FormData(e.target);if(!getPoint(f,'origin')||!getPoint(f,'destination')){setError(t('chooseLocation'));e.target.querySelector('[data-location]')?.focus();render();return}const actorId=state.user?.id;const savedSearchDraft={id:e.target.id,values:Object.fromEntries(f.entries())};state.busy=true;markPending(e.target,t('pending'));try{const out=await api('/api/search','POST',{origin:getPoint(f,'origin'),destination:getPoint(f,'destination'),window_start:localIso(f.get('window_start')),window_end:localIso(f.get('window_end')),seats:1});state.results=out;await refreshState();state.form=state.user?.id===actorId?savedSearchDraft:null;if(state.form)state.formDrafts['search-form']=state.form;setNotice('Search saved.');nav('results')}catch(err){if(err.status===401)await expireSession();else setError(err)}finally{state.busy=false;clearPending();render()}}
async function rate(e){e.preventDefault();if(state.busy)return;let f=new FormData(e.target);state.busy=true;markPending(e.target,t('pending'));try{await api('/api/rate','POST',{booking_id:e.target.dataset.id,stars:Number(f.get('stars')),comment:f.get('comment')});setNotice(t('rateSubmitted'));await refreshState();nav('bookings')}catch(err){if(err.status===401)await expireSession();else setError(err)}finally{state.busy=false;clearPending();render()}}
async function submitSafety(e){e.preventDefault();if(state.busy)return;const f=new FormData(e.target);const bookingId=e.target.dataset.id;const key=state.reportKeys[bookingId]||(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`);state.reportKeys[bookingId]=key;state.busy=true;markPending(e.target,t('pending'));try{await api('/api/report_safety','POST',{booking_id:e.target.dataset.id,category:f.get('category'),details:f.get('details'),idempotency_key:key});await refreshState();delete state.reportKeys[bookingId];state.form=null;state.skipCaptureOnce=true;setNotice(t('reportSent'))}catch(err){if(err.status===401)await expireSession();else setError(err)}finally{state.busy=false;clearPending();render()}}
async function refreshState(){if(!state.user)return;let d=await api('/api/state');if(d.user?.id!==state.user.id){community.destroy();clearTripSharingState();state.user=d.user||null;state.preview=null;state.results=null;state.ops=null;state.form=null;state.formDrafts={};state.routePoints={origin:null,destination:null};state.blockConfirm=null;state.reportKeys={};state.adminResolutionDrafts={};state.menuOpen=false;state.passwordVisible=false;state.skipCaptureOnce=true;await loadBootstrap();}state.user=d.user||state.user;state.data={...state.data,...d};return d}
async function loadOps(){if(!canReadOps()){state.ops=null;return}state.ops=await api('/api/operations')}
async function act(action,id){if(state.busy)return;if(action==='resolve-report'&&!canResolveSafety()){setError({status:403,message:'forbidden'});render();return}const resolveForm=action==='resolve-report'?document.querySelector(`.resolve-form[data-report-id="${CSS.escape(id)}"]`):null;if(resolveForm&&!resolveForm.reportValidity())return;const resolutionText=resolveForm?new FormData(resolveForm).get('resolution'):null;if(action==='resolve-report')state.adminResolutionDrafts[id]=resolutionText;state.error='';state.notice='';try{if(action==='use-telugu'){captureDraft();changeLanguage('te');render();return}if(action==='menu-toggle'){state.menuOpen=!state.menuOpen;render();return}if(action==='password-toggle'){const input=document.querySelector('#login-password'),button=document.querySelector('[data-action="password-toggle"]');if(input&&button){state.passwordVisible=!state.passwordVisible;input.type=state.passwordVisible?'text':'password';button.setAttribute('aria-label',t(state.passwordVisible?'hidePassword':'showPassword'));button.innerHTML=icon(state.passwordVisible?'eyeSlash':'eye',24)}return}if(action==='home-search'){openComposer('search-form');return}if(action==='home-drive'){openComposer('drive-form');return}if(action==='swap-route'){swapRoute(document.querySelector('#home-route-form'));return}if(action==='retry-bootstrap'){state.busy=true;try{await loadBootstrap();state.error='';if(state.user)await refreshState()}catch(e){setError(e)}finally{state.busy=false;render()}return}if(action==='clear-message'){state.error='';render();return}if(action==='back'){history.back();return}if(action==='start-block'){state.blockConfirm=id;render();return}if(action==='cancel-block'){state.blockConfirm=null;render();return}if(action==='refresh'){state.busy=true;await refreshState();if(currentRoute()==='operations'&&canReadOps())await loadOps();setNotice(t('saved'));render();return}if(action==='logout'){community.destroy();clearTripSharingState();state.busy=true;if(state.liveCleanup){state.liveCleanup();state.liveCleanup=null}state.liveBookingId=null;state.liveElement=null;await api('/api/logout','POST',{});state.user=null;state.data={trips:[],bookings:[],requests:[],ratings:[]};state.preview=null;state.results=null;state.form=null;state.formDrafts={};state.routePoints={origin:null,destination:null};state.blockConfirm=null;state.reportKeys={};state.adminResolutionDrafts={};state.skipCaptureOnce=true;nav('login');return}
  state.busy=true;render();let actionMap={publish:()=>api('/api/publish','POST',{preview_id:state.preview?.id}), 'request-seat':()=>api('/api/request','POST',{match_id:id}), accept:()=>api('/api/accept','POST',{booking_id:id}), decline:()=>api('/api/decline','POST',{booking_id:id,reason:t('declinedByDriver')}), 'cancel-booking':()=>api('/api/cancel_booking','POST',{booking_id:id,reason:t('cancelledByUser')}), 'board-segment':()=>api('/api/board_segment','POST',{booking_id:id}), 'complete-segment':()=>api('/api/complete_segment','POST',{booking_id:id}), 'start-trip':()=>api('/api/start_trip','POST',{trip_id:id}), 'complete-trip':()=>api('/api/complete_trip','POST',{trip_id:id}), 'cancel-trip':()=>api('/api/cancel_trip','POST',{trip_id:id,reason:t('cancelledByDriver')}), 'confirm-block':()=>api('/api/block_person','POST',{booking_id:id}), 'resolve-report':()=>api('/api/resolve_report','POST',{report_id:id,resolution:resolutionText})};if(actionMap[action]){try{await actionMap[action]()}catch(err){if(![400,401,403,409].includes(err.status)){setNotice(t('retrying'));await refreshState();throw err}throw err}await refreshState();setNotice(t('saved'))}if(action==='confirm-block')state.blockConfirm=null;if(action==='resolve-report')delete state.adminResolutionDrafts[id];if(action==='publish'){state.preview=null;state.form=null;state.formDrafts={};state.routePoints={origin:null,destination:null};state.skipCaptureOnce=true;nav('journeys')}if(action==='request-seat')nav('bookings');if(currentRoute()==='operations'&&canReadOps())await loadOps();
 }catch(err){if(err.status===401)await expireSession();else setError(err)}finally{state.busy=false;render()}}
async function loadBootstrap(){state.boot=await api('/api/bootstrap');state.csrf=state.boot.csrf_token;state.user=state.boot.user}
async function expireSession(){community.destroy();clearTripSharingState();if(state.liveCleanup){state.liveCleanup();state.liveCleanup=null}state.liveBookingId=null;state.liveElement=null;state.user=null;state.data={trips:[],bookings:[],requests:[],ratings:[]};state.preview=null;state.results=null;state.ops=null;state.form=null;state.formDrafts={};state.routePoints={origin:null,destination:null};state.blockConfirm=null;state.reportKeys={};state.adminResolutionDrafts={};state.skipCaptureOnce=true;try{await loadBootstrap()}catch{}state.error='Session expired. Sign in again.';state.notice='';}
async function init(){try{await loadBootstrap();if(state.user){await refreshState();if(currentRoute()==='operations'&&canReadOps())await loadOps()}}catch(e){setError(e)}render()}
window.addEventListener('hashchange',async()=>{
  state.error='';state.menuOpen=false;const route=currentRoute(),actor=state.user?.id;
  if(state.renderedRoute!==route)render();
  if(!state.user)return;
  try{await refreshState();if(currentRoute()!==route)return;if(route==='operations'&&canReadOps())await loadOps();
    const safeView=['inbox','bookings','journeys','operations'].includes(route)||route.startsWith('trip/');
    if(state.user?.id!==actor||safeView)render();
  }catch(e){if(currentRoute()===route){setError(e);render()}}
});
let pollTimer;document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInterval(pollTimer)}else if(state.user)startPolling()});function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(!state.user||document.hidden)return;const old=state.user.id;try{const before=JSON.stringify(state.data);const d=await refreshState();const changed=JSON.stringify(state.data)!==before;if(d.user?.id!==old){state.preview=null;state.results=null;setNotice('Account changed in another tab. Current account state loaded.');render()}else{const route=currentRoute();const safeView=route==='inbox'||route==='bookings'||route==='journeys'||route.startsWith('trip/');const active=document.activeElement;const typing=active&&app.contains(active)&&(['INPUT','SELECT','TEXTAREA'].includes(active.tagName)||active.isContentEditable);if(changed&&safeView&&!typing&&!state.busy)render()}}catch(e){if(e.status===401){await expireSession();render()}}},15000)}
init().then(startPolling);
